/* Caffeine Theme — Tailwind v3 (hex) */
/* Channel triplets — consume via rgb(var(--token)). See tailwind.config snippet in docs. */

@layer base {
  /* Caffeine Theme - Auto-generated from tweakcn */

  /* Light mode (:root) */
  :root {
    --background: 248 248 248;
    --foreground: 31 31 31;
    --card: 252 252 252;
    --card-foreground: 31 31 31;
    --popover: 252 252 252;
    --popover-foreground: 31 31 31;
    --primary: 99 73 63;
    --primary-foreground: 255 255 255;
    --secondary: 255 223 181;
    --secondary-foreground: 89 45 28;
    --muted: 238 238 238;
    --muted-foreground: 99 99 99;
    --accent: 232 232 232;
    --accent-foreground: 31 31 31;
    --destructive: 229 80 50;
    --destructive-foreground: 255 255 255;
    --border: 215 215 215;
    --input: 215 215 215;
    --ring: 99 73 63;
    --chart-1: 99 73 63;
    --chart-2: 255 223 181;
    --chart-3: 232 232 232;
    --chart-4: 255 231 199;
    --chart-5: 99 73 63;
    --radius: 0.5rem;
    --sidebar: 252 252 252;
    --sidebar-foreground: 36 36 36;
    --sidebar-primary: 53 53 53;
    --sidebar-primary-foreground: 252 252 252;
    --sidebar-accent: 248 248 248;
    --sidebar-accent-foreground: 53 53 53;
    --sidebar-border: 235 235 235;
    --sidebar-ring: 180 180 180;
    --font-sans:
      ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
      "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono:
      ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New", monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
    --tracking-normal: 0em;
  }

  /* Dark mode (.dark) */
  .dark {
    --background: 18 18 18;
    --foreground: 238 238 238;
    --card: 24 24 24;
    --card-foreground: 238 238 238;
    --popover: 24 24 24;
    --popover-foreground: 238 238 238;
    --primary: 252 223 194;
    --primary-foreground: 10 25 26;
    --secondary: 58 49 40;
    --secondary-foreground: 252 223 194;
    --muted: 34 34 34;
    --muted-foreground: 180 180 180;
    --accent: 43 43 43;
    --accent-foreground: 238 238 238;
    --destructive: 229 80 50;
    --destructive-foreground: 255 255 255;
    --border: 33 31 26;
    --input: 72 72 72;
    --ring: 252 223 194;
    --chart-1: 252 223 194;
    --chart-2: 58 49 40;
    --chart-3: 43 43 43;
    --chart-4: 66 57 48;
    --chart-5: 252 223 194;
    --radius: 0.5rem;
    --sidebar: 24 24 29;
    --sidebar-foreground: 245 245 245;
    --sidebar-primary: 29 78 218;
    --sidebar-primary-foreground: 255 255 255;
    --sidebar-accent: 38 38 43;
    --sidebar-accent-foreground: 245 245 245;
    --sidebar-border: 38 38 43;
    --sidebar-ring: 211 211 219;
    --font-sans:
      ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI",
      Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif,
      "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
    --font-mono:
      ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono",
      "Courier New", monospace;
    --shadow-color: 0 0 0;
    --shadow-opacity: 0.1;
    --shadow-blur: 3px;
    --shadow-spread: 0px;
    --shadow-offset-x: 0;
    --shadow-offset-y: 1px;
    --letter-spacing: 0em;
    --spacing: 0.25rem;
    --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
    --shadow-sm:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
    --shadow-md:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
    --shadow-lg:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
    --shadow-xl:
      0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
    --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  }

}
